-- Seed for contract_clauses (generated from FAR_DFAR_Clause_Review_2024.xlsx)
-- 1,373 canonical clauses, one row per (standard, clause_number).
-- Idempotent: uses INSERT ... ON DUPLICATE KEY UPDATE so re-running refreshes
-- catalog fields but PRESERVES any admin-set classification/updated_by.

ON DUPLICATE KEY UPDATE
  title=VALUES(title), clause_text=VALUES(clause_text),
  effective_date=VALUES(effective_date), reviewer=VALUES(reviewer),
  date_reviewed=VALUES(date_reviewed), comments=VALUES(comments),
  sources=VALUES(sources),
  classification=IF(updated_by IS NULL, VALUES(classification), classification);

