('CFR','15 CFR 700.13','IS PART OF THE DEFENSE PRIORITIES AND ALLOCATIONS SYSTEM (DPAS), WHICH ENSURES THAT INDUSTRIAL RESOURCES ARE AVAILABLE TO MEET NATIONAL DEFENSE AND EMERGENCY PREPAREDNESS REQUIREMENTS. THE REGULATION ESTABLISHES MANDATORY ACCEPTANCE AND REJECTION RULES FOR RATED ORDERS, WHICH ARE ORDERS ASSIGNED PRIORITY RATINGS (DO OR DX) UNDER THE DPAS PROGRAM',NULL,'','Y','MARINA KEENAN','2026-05-15 00:00:00',NULL,'FAR & DFAR Review'),
('CFR','15 U.S.C. 645','OFFENSES AND PENALTIES',NULL,'','Y','MARINA KEENAN','2026-05-18 00:00:00',NULL,'FAR & DFAR Review'),
('CFR','22 CFR 121','SPECIFIES THE USML CATEGORIES, INCLUDING FIREARMS, MILITARY ELECTRONICS, AIRCRAFT, AND OTHER DEFENSE-RELATED ITEMS. IT IDENTIFIES WHICH ITEMS REQUIRE EXPORT LICENSES AND ESTABLISHES THE BASIS FOR DETERMINING WHETHER A PRODUCT OR SERVICE FALLS UNDER ITAR CONTROL',NULL,'','N/A','MARINA KEENAN','2026-05-29 00:00:00',NULL,'FAR & DFAR Review'),
('CFR','22 CFR 123','DETAILS THE LICENSING PROCESS FOR EXPORTING DEFENSE ARTICLES, INCLUDING APPLICATIONS, APPROVALS, AND CONDITIONS. IT ESTABLISHES THE PROCEDURES FOR OBTAINING EXPORT LICENSES AND TEMPORARY IMPORT AUTHORIZATIONS',NULL,'','Y','MARINA KEENAN','2026-05-29 00:00:00',NULL,'FAR & DFAR Review'),
('CFR','22 CFR 124','GOVERNS TECHNICAL ASSISTANCE AGREEMENTS (TAAS) AND MANUFACTURING LICENSE AGREEMENTS (MLAS) WITH FOREIGN GOVERNMENTS OR ENTITIES. THESE AGREEMENTS REGULATE THE TRANSFER OF DEFENSE TECHNOLOGY AND SERVICES ABROAD',NULL,'','N/A','MARINA KEENAN','2026-05-29 00:00:00',NULL,'FAR & DFAR Review'),
('CFR','22 CFR 125','ADDRESSES EXPORT LICENSES FOR TECHNICAL DATA, INCLUDING BLUEPRINTS, SOFTWARE, AND OTHER CONTROLLED INFORMATION. IT ENSURES THAT SENSITIVE DEFENSE INFORMATION IS SHARED ONLY WITH AUTHORIZED FOREIGN PARTIES',NULL,'','Y','MARINA KEENAN','2026-05-29 00:00:00',NULL,'FAR & DFAR Review'),
('CFR','22 CFR 126','OUTLINES POLICIES FOR EXPORT APPROVALS, INCLUDING PROHIBITED DESTINATIONS, END-USE RESTRICTIONS, AND EMBARGOES. IT ALSO COVERS TEMPORARY IMPORT CONTROLS FOR DEFENSE ARTICLES',NULL,'','Y','MARINA KEENAN','2026-05-29 00:00:00',NULL,'FAR & DFAR Review'),
('CFR','22 CFR 127','ESTABLISHES PENALTIES FOR VIOLATIONS OF ITAR, INCLUDING CIVIL AND CRIMINAL SANCTIONS. IT ALSO DESCRIBES PROCEDURES FOR INVESTIGATIONS AND ENFORCEMENT ACTIONS',NULL,'','Y','MARINA KEENAN','2026-05-29 00:00:00',NULL,'FAR & DFAR Review'),
('CFR','22 CFR 128','PROVIDES PROCEDURES FOR ADMINISTRATIVE HEARINGS BEFORE A PRESIDING OFFICIAL REGARDING ITAR VIOLATIONS, INCLUDING THE SUBMISSION OF EVIDENCE AND REPORTING REQUIREMENTS',NULL,'','Y','MARINA KEENAN','2026-05-29 00:00:00',NULL,'FAR & DFAR Review'),
('CFR','22 CFR 129','REGULATES BROKERING OF DEFENSE ARTICLES AND SERVICES, INCLUDING REGISTRATION, REPORTING, AND LICENSING REQUIREMENTS FOR U.S. AND FOREIGN BROKER',NULL,'','N/A','MARINA KEENAN','2026-05-29 00:00:00',NULL,'FAR & DFAR Review'),
('CFR','22 CFR 130','CONTAINS GENERAL PROVISIONS, INCLUDING RECORDKEEPING, REPORTING, AND COMPLIANCE REQUIREMENTS THAT APPLY ACROSS ITAR-REGULATED ACTIVITIES',NULL,'','N/A','MARINA KEENAN','2026-05-29 00:00:00',NULL,'FAR & DFAR Review'),
('CFR','41 CFR 600-300.5','SETS OUT THE EQUAL OPPORTUNITY REQUIREMENTS THAT MUST BE INCLUDED IN CERTAIN FEDERAL CONTRACTS AND SUBCONTRACTS, ENSURING THAT PROTECTED VETERANS ARE NOT DISCRIMINATED AGAINST IN EMPLOYMENT.',NULL,'','Y','MARINA KEENAN','2026-05-29 00:00:00',NULL,'FAR & DFAR Review'),
('CFR','41 CFR 60-741.5','EQUAL OPPORTUNITY CLAUSE THAT CONTRACTORS AND SUBCONTRACTORS MUST INCLUDE IN THEIR CONTRACTS. THIS CLAUSE MANDATES THAT THEY SHALL ABIDE BY THE REQUIREMENTS OF THIS REGULATION, WHICH PROHIBITS DISCRIMINATION AGAINST QUALIFIED INDIVIDUALS BASED ON THEIR DISABILITY STATUS',NULL,'','Y','MARINA KEENAN','2026-05-29 00:00:00',NULL,'FAR & DFAR Review'),
('CFR','29 CFR 1910','GOVERNS LABOR REGULATIONS IN THE U.S. SPECIFICALLY, PART 1910 SETS STANDARDS FOR GENERAL INDUSTRY TO ENSURE SAFE AND HEALTHFUL WORKING CONDITIONS. THESE REGULATIONS ARE ENFORCED BY THE OCCUPATIONAL SAFETY AND HEALTH ADMINISTRATION (OSHA) AND COVER A WIDE RANGE OF WORKPLACE HAZARDS, FROM MACHINERY AND ELECTRICAL SAFETY TO CHEMICAL EXPOSURE AND EMERGENCY PROCEDURES',NULL,'','Y','ANA CELAYA','2026-06-05 00:00:00',NULL,'FAR & DFAR Review'),
('CFR','29 CFR 1926','SET OF FEDERAL REGULATIONS ISSUED BY THE OCCUPATIONAL SAFETY AND HEALTH ADMINISTRATION (OSHA) THAT GOVERNS SAFETY AND HEALTH REQUIREMENTS FOR CONSTRUCTION WORK IN THE UNITED STATES . IT APPLIES TO ACTIVITIES SUCH AS CONSTRUCTION, ALTERATION, REPAIR, DEMOLITION, PAINTING, AND DECORATING OF STRUCTURES, INCLUDING RESIDENTIAL, COMMERCIAL, AND CIVIL ENGINEERING PROJECTS',NULL,'','Y','ANA CELAYA','2026-06-05 00:00:00',NULL,'FAR & DFAR Review'),
('FAR','46.407','ESTABLISHES THE PROCEDURES FOR HANDLING NONCONFORMING SUPPLIES OR SERVICES IN GOVERNMENT CONTRACTS. THE GENERAL RULE IS THAT THE CONTRACTING OFFICER SHOULD REJECT ANY SUPPLIES OR SERVICES THAT FAIL TO MEET CONTRACT SPECIFICATIONS. HOWEVER, IN CERTAIN CIRCUMSTANCES, ACCEPTANCE OR CONDITIONAL ACCEPTANCE MAY BE IN THE GOVERNMENT’S INTEREST, SUCH AS FOR REASONS OF ECONOMY, URGENCY, OR TECHNICAL FEASIBILITY',NULL,'','Y','MARINA KEENAN','2026-06-05 00:00:00',NULL,'FAR & DFAR Review'),
